BEGIN;SET LOCAL lock_timeout='5s';DO $guard$ BEGIN IF md5(pg_get_functiondef('play_buy_cart(jsonb,uuid)'::regprocedure))<>'7f05cb0c04f19a596a22a8853f3f9116' OR (SELECT proacl::text FROM pg_proc WHERE oid='play_buy_cart(jsonb,uuid)'::regprocedure) IS DISTINCT FROM '{=X/postgres,postgres=X/postgres,anon=X/postgres,authenticated=X/postgres,service_role=X/postgres}' THEN RAISE EXCEPTION 'POUCH_CHECKOUT_SOURCE_OR_ACL_DRIFT';END IF;END $guard$;
DO $replace$ BEGIN EXECUTE convert_from(decode('','base64'),'UTF8');END $replace$;COMMIT;
